#!/usr/bin/env python3
"""JAX + SMT leg for foundation R2 quotient stability v2.

This rebuild fixes the prior decorative encoding: z3/cvc5 relation predicates
are equalities over Real expectation variables bound to computed Tr(rho O)
values. No Bool relation matrix is asserted into either solver.
"""

from __future__ import annotations

import datetime as _dt
import json
import sys
from fractions import Fraction
from pathlib import Path
from typing import Any

import cvc5
import jax

jax.config.update("jax_enable_x64", True)

import jax.numpy as jnp
import z3


OBJECT_ID = "foundation_r2_quotient_stability_v2"
ENGINE = "jax"
RUNG_ID = "foundation_r2_quotient_stability_v2"
ROOT = Path("/Users/joshuaeisenhart/Codex-Ratchet")
SOURCE_PATH = ROOT / "system_v5/ops/formal_scouts/foundation_r2_quotient_stability_jax_leg.py"
RESULT_PATH = ROOT / "system_v5/ops/formal_scouts/results/foundation_r2_quotient_stability_jax_results.json"
TOL = 1.0e-10

classification = "scratch_diagnostic"
CLASSIFICATION = classification
promotion_allowed = False
PROMOTION_ALLOWED = promotion_allowed
formal_admission_allowed = False
FORMAL_ADMISSION_ALLOWED = formal_admission_allowed
reads_peer_result = False
READS_PEER_RESULT = reads_peer_result

TOOL_MANIFEST = {
    "jax": {"tried": True, "used": True, "reason": "supportive x64 carrier matrix and Tr(rho O) expectation computation"},
    "jax.numpy": {"tried": True, "used": True, "reason": "supportive complex128 density matrices, projectors, and unitary images"},
    "z3": {"tried": True, "used": True, "reason": "load-bearing proof over Real expectation variables bound to computed carrier expectations"},
    "cvc5": {"tried": True, "used": True, "reason": "load-bearing independent proof over the same Real expectation-variable encoding"},
}
TOOL_INTEGRATION_DEPTH = {"jax": "supportive", "jax.numpy": "supportive", "z3": "load_bearing", "cvc5": "load_bearing"}

I2 = jnp.eye(2, dtype=jnp.complex128)
PZ0 = jnp.asarray([[1.0, 0.0], [0.0, 0.0]], dtype=jnp.complex128)
U_PHASE = jnp.asarray([[1.0, 0.0], [0.0, 1.0j]], dtype=jnp.complex128)
U_H = jnp.asarray([[1.0, 1.0], [1.0, -1.0]], dtype=jnp.complex128) / jnp.sqrt(jnp.asarray(2.0, dtype=jnp.float64))


def py_float(value: Any) -> float:
    return float(jax.device_get(jnp.real(value)))


def rounded(value: Any, digits: int = 12) -> float:
    return round(py_float(value), digits)


def frac(value: float) -> Fraction:
    return Fraction(str(round(float(value), 12))).limit_denominator(10**12)


def ket(values: list[complex]) -> jax.Array:
    vec = jnp.asarray(values, dtype=jnp.complex128)
    return vec / jnp.sqrt(jnp.vdot(vec, vec))


def density(vec: jax.Array) -> jax.Array:
    return jnp.outer(vec, jnp.conj(vec))


def candidates() -> list[dict[str, Any]]:
    s2 = jnp.sqrt(jnp.asarray(2.0, dtype=jnp.float64))
    states = {
        "pure_z0": ket([1.0 + 0.0j, 0.0 + 0.0j]),
        "pure_z1": ket([0.0 + 0.0j, 1.0 + 0.0j]),
        "pure_x_plus": ket([1.0 + 0.0j, 1.0 + 0.0j]),
        "pure_x_minus": ket([1.0 + 0.0j, -1.0 + 0.0j]),
        "pure_y_plus": jnp.asarray([1.0 + 0.0j, 0.0 + 1.0j], dtype=jnp.complex128) / s2,
        "pure_y_minus": jnp.asarray([1.0 + 0.0j, 0.0 - 1.0j], dtype=jnp.complex128) / s2,
    }
    rows = [{"id": name, "rho": density(vec)} for name, vec in states.items()]
    rows.append({"id": "maximally_mixed", "rho": 0.5 * I2})
    return rows


def active_probe_family() -> list[dict[str, Any]]:
    return [{"name": "Z0", "effect": PZ0, "description": "computational-basis |0><0| projector"}]


def expectation(rho: jax.Array, effect: jax.Array) -> float:
    return rounded(jnp.trace(rho @ effect), 12)


def expectation_table(rows: list[dict[str, Any]], probes: list[dict[str, Any]]) -> list[list[float]]:
    return [[expectation(row["rho"], probe["effect"]) for probe in probes] for row in rows]


def apply_unitary(rho: jax.Array, unitary: jax.Array) -> jax.Array:
    return unitary @ rho @ jnp.conj(unitary.T)


def image_rows(rows: list[dict[str, Any]], unitary: jax.Array) -> list[dict[str, Any]]:
    return [{"id": row["id"], "rho": apply_unitary(row["rho"], unitary)} for row in rows]


def signature_key(sig: list[float]) -> str:
    return json.dumps(sig, sort_keys=True, separators=(",", ":"))


def quotient(rows: list[dict[str, Any]], probes: list[dict[str, Any]], name: str) -> dict[str, Any]:
    table = expectation_table(rows, probes) if probes else [[] for _ in rows]
    classes: dict[str, dict[str, Any]] = {}
    for row, sig in zip(rows, table, strict=True):
        key = signature_key(sig)
        classes.setdefault(key, {"members": [], "signature": sig})
        classes[key]["members"].append(row["id"])
    ordered = [
        {"class_id": f"{name}_q{idx}", "members": sorted(classes[key]["members"]), "signature": classes[key]["signature"]}
        for idx, key in enumerate(sorted(classes))
    ]
    return {"name": name, "probe_names": [probe["name"] for probe in probes], "class_count": len(ordered), "classes": ordered}


def relation_from_table(table: list[list[float]]) -> list[list[bool]]:
    return [[table[i] == table[j] for j in range(len(table))] for i in range(len(table))]


def relation_report(rel: list[list[bool]]) -> dict[str, bool]:
    n = len(rel)
    reflexive = all(rel[i][i] for i in range(n))
    symmetric = all((not rel[i][j]) or rel[j][i] for i in range(n) for j in range(n))
    transitive = all((not rel[i][j]) or (not rel[j][k]) or rel[i][k] for i in range(n) for j in range(n) for k in range(n))
    return {"reflexive": reflexive, "symmetric": symmetric, "transitive": transitive, "is_equivalence_relation": reflexive and symmetric and transitive}


def stability_report(base_rel: list[list[bool]], image_rel: list[list[bool]], ids: list[str]) -> dict[str, Any]:
    violating = [
        {"left": ids[i], "right": ids[j]}
        for i in range(len(ids))
        for j in range(len(ids))
        if base_rel[i][j] and not image_rel[i][j]
    ]
    return {"stable": not violating, "violating_pairs": violating}


def constraints_report(rows: list[dict[str, Any]], probes: list[dict[str, Any]]) -> dict[str, Any]:
    details = []
    for row in rows:
        rho = row["rho"]
        eigs = jnp.linalg.eigvalsh((rho + jnp.conj(rho.T)) / 2.0)
        details.append(
            {
                "id": row["id"],
                "trace_residual": py_float(jnp.abs(jnp.trace(rho) - 1.0)),
                "hermitian_residual": py_float(jnp.linalg.norm(rho - jnp.conj(rho.T))),
                "min_eigenvalue": py_float(jnp.min(eigs)),
                "active_expectations": [expectation(rho, probe["effect"]) for probe in probes],
                "psd": py_float(jnp.min(eigs)) >= -TOL,
            }
        )
    return {
        "trace_one": all(row["trace_residual"] <= TOL for row in details),
        "hermitian": all(row["hermitian_residual"] <= TOL for row in details),
        "psd": all(row["psd"] for row in details),
        "details": details,
    }


def unitary_residual(unitary: jax.Array) -> float:
    return py_float(jnp.linalg.norm(jnp.conj(unitary.T) @ unitary - I2))


def z3_real_value(value: float) -> z3.RatNumRef:
    f = frac(value)
    return z3.RealVal(f"{f.numerator}/{f.denominator}")


def z3_vars(prefix: str, table: list[list[float]]) -> tuple[list[list[z3.ArithRef]], list[z3.BoolRef]]:
    vars_ = [[z3.Real(f"{prefix}_e_{i}_{m}") for m in range(len(table[i]))] for i in range(len(table))]
    constraints = [vars_[i][m] == z3_real_value(table[i][m]) for i in range(len(table)) for m in range(len(table[i]))]
    return vars_, constraints


def z3_rel(vars_: list[list[z3.ArithRef]], i: int, j: int) -> z3.BoolRef:
    equalities = [vars_[i][m] == vars_[j][m] for m in range(len(vars_[i]))]
    return z3.And(*equalities) if equalities else z3.BoolVal(True)


def z3_no_violation(base_table: list[list[float]], image_table: list[list[float]]) -> dict[str, Any]:
    base_vars, base_constraints = z3_vars("base", base_table)
    image_vars, image_constraints = z3_vars("image", image_table)
    n = len(base_table)
    violations: list[z3.BoolRef] = []
    violations.extend(z3.Not(z3_rel(base_vars, i, i)) for i in range(n))
    violations.extend(z3.And(z3_rel(base_vars, i, j), z3.Not(z3_rel(base_vars, j, i))) for i in range(n) for j in range(n))
    violations.extend(
        z3.And(z3_rel(base_vars, i, j), z3_rel(base_vars, j, k), z3.Not(z3_rel(base_vars, i, k)))
        for i in range(n)
        for j in range(n)
        for k in range(n)
    )
    violations.extend(z3.And(z3_rel(base_vars, i, j), z3.Not(z3_rel(image_vars, i, j))) for i in range(n) for j in range(n))
    solver = z3.Solver()
    solver.add(*(base_constraints + image_constraints))
    solver.add(z3.Or(*violations))
    return {"verdict": str(solver.check()), "asserted_real_equalities": len(base_constraints) + len(image_constraints), "violation_terms": len(violations)}


def z3_stability_violation(base_table: list[list[float]], image_table: list[list[float]], ids: list[str]) -> dict[str, Any]:
    base_vars, base_constraints = z3_vars("bad_base", base_table)
    image_vars, image_constraints = z3_vars("bad_image", image_table)
    n = len(base_table)
    violations = [z3.And(z3_rel(base_vars, i, j), z3.Not(z3_rel(image_vars, i, j))) for i in range(n) for j in range(n)]
    solver = z3.Solver()
    solver.add(*(base_constraints + image_constraints))
    solver.add(z3.Or(*violations))
    verdict = str(solver.check())
    witness = None
    if verdict == "sat":
        model = solver.model()
        for idx, term in enumerate(violations):
            if z3.is_true(model.evaluate(term, model_completion=True)):
                i, j = divmod(idx, n)
                witness = {"indices": [i, j], "ids": [ids[i], ids[j]]}
                break
    return {"verdict": verdict, "witness": witness, "asserted_real_equalities": len(base_constraints) + len(image_constraints)}


def cvc5_real_value(solver: cvc5.Solver, value: float) -> Any:
    f = frac(value)
    return solver.mkReal(f.numerator, f.denominator)


def cvc5_and(solver: cvc5.Solver, terms: list[Any]) -> Any:
    if not terms:
        return solver.mkBoolean(True)
    return terms[0] if len(terms) == 1 else solver.mkTerm(cvc5.Kind.AND, *terms)


def cvc5_or(solver: cvc5.Solver, terms: list[Any]) -> Any:
    if not terms:
        return solver.mkBoolean(False)
    return terms[0] if len(terms) == 1 else solver.mkTerm(cvc5.Kind.OR, *terms)


def cvc5_vars(solver: cvc5.Solver, prefix: str, table: list[list[float]]) -> tuple[list[list[Any]], list[Any]]:
    real_sort = solver.getRealSort()
    vars_ = [[solver.mkConst(real_sort, f"{prefix}_e_{i}_{m}") for m in range(len(table[i]))] for i in range(len(table))]
    constraints = [
        solver.mkTerm(cvc5.Kind.EQUAL, vars_[i][m], cvc5_real_value(solver, table[i][m]))
        for i in range(len(table))
        for m in range(len(table[i]))
    ]
    return vars_, constraints


def cvc5_rel(solver: cvc5.Solver, vars_: list[list[Any]], i: int, j: int) -> Any:
    return cvc5_and(solver, [solver.mkTerm(cvc5.Kind.EQUAL, vars_[i][m], vars_[j][m]) for m in range(len(vars_[i]))])


def cvc5_no_violation(base_table: list[list[float]], image_table: list[list[float]]) -> dict[str, Any]:
    solver = cvc5.Solver()
    solver.setLogic("QF_LRA")
    base_vars, base_constraints = cvc5_vars(solver, "base", base_table)
    image_vars, image_constraints = cvc5_vars(solver, "image", image_table)
    for constraint in base_constraints + image_constraints:
        solver.assertFormula(constraint)
    n = len(base_table)
    violations: list[Any] = []
    violations.extend(solver.mkTerm(cvc5.Kind.NOT, cvc5_rel(solver, base_vars, i, i)) for i in range(n))
    violations.extend(
        cvc5_and(solver, [cvc5_rel(solver, base_vars, i, j), solver.mkTerm(cvc5.Kind.NOT, cvc5_rel(solver, base_vars, j, i))])
        for i in range(n)
        for j in range(n)
    )
    violations.extend(
        cvc5_and(solver, [cvc5_rel(solver, base_vars, i, j), cvc5_rel(solver, base_vars, j, k), solver.mkTerm(cvc5.Kind.NOT, cvc5_rel(solver, base_vars, i, k))])
        for i in range(n)
        for j in range(n)
        for k in range(n)
    )
    violations.extend(
        cvc5_and(solver, [cvc5_rel(solver, base_vars, i, j), solver.mkTerm(cvc5.Kind.NOT, cvc5_rel(solver, image_vars, i, j))])
        for i in range(n)
        for j in range(n)
    )
    solver.assertFormula(cvc5_or(solver, violations))
    return {"verdict": str(solver.checkSat()), "asserted_real_equalities": len(base_constraints) + len(image_constraints), "violation_terms": len(violations)}


def cvc5_stability_violation(base_table: list[list[float]], image_table: list[list[float]]) -> dict[str, Any]:
    solver = cvc5.Solver()
    solver.setLogic("QF_LRA")
    base_vars, base_constraints = cvc5_vars(solver, "bad_base", base_table)
    image_vars, image_constraints = cvc5_vars(solver, "bad_image", image_table)
    for constraint in base_constraints + image_constraints:
        solver.assertFormula(constraint)
    n = len(base_table)
    violations = [
        cvc5_and(solver, [cvc5_rel(solver, base_vars, i, j), solver.mkTerm(cvc5.Kind.NOT, cvc5_rel(solver, image_vars, i, j))])
        for i in range(n)
        for j in range(n)
    ]
    solver.assertFormula(cvc5_or(solver, violations))
    return {"verdict": str(solver.checkSat()), "asserted_real_equalities": len(base_constraints) + len(image_constraints)}


def main() -> int:
    rows = candidates()
    probes = active_probe_family()
    ids = [row["id"] for row in rows]
    base_table = expectation_table(rows, probes)
    admitted_table = expectation_table(image_rows(rows, U_PHASE), probes)
    nonadmitted_table = expectation_table(image_rows(rows, U_H), probes)
    base_rel = relation_from_table(base_table)
    admitted_rel = relation_from_table(admitted_table)
    nonadmitted_rel = relation_from_table(nonadmitted_table)

    q = quotient(rows, probes, "active_M_Z0")
    dropped_q = quotient(rows, [], "dropped_M_empty")
